use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = herd.lineup();
    var entries: List<String> = [];
    var i = 0;
    while i < lineup.len() {
        let pony = lineup.get(index: i)?;
        let fed = herd.feed(pony: pony, scoops: 3);
        let entry = ledger.entry(pony: fed);
        entries.push(item: entry);
        i = i + 1;
    }
    let joined = entries.join(sep: ",");
    io.write(text: joined)?;
    return Ok(unit);
}

