use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        let plank = match planks.get(index: i) {
            Some(p) => p,
            None => stock.Plank { grain: "", length: 0 },
        };
        if rules.keeps(plank: plank) {
            let label = rules.label(plank: plank);
            labels.push(item: label);
        }
        i = i + 1;
    }
    labels.join(sep: ",")
}

